  `<rect x="${x}" y="${y}" width="${label.length * 9 + 24}" height="26" rx="13" fill="${fill}"/><text x="${x + 12}" y="${y + 18}" font-family="Arial" font-size="14" fill="${ink}">${label}</text>`;
